import os
import sys
import tempfile

import torch.distributed as dist
import torch.multiprocessing as mp

sys.path.insert(0, "/workspace/src")
from trl.trainer.grpo_trainer import gather_object


def flush(pending):
    local_metrics = {name: sum(values) / len(values) for name, values in pending.items()}
    gathered_metrics = gather_object([local_metrics])
    return {
        name: sum(values) / len(values)
        for name in sorted({name for metrics in gathered_metrics for name in metrics})
        for values in [[metrics[name] for metrics in gathered_metrics if name in metrics]]
    }


def worker(rank, store_path):
    dist.init_process_group("gloo", init_method=f"file://{store_path}", rank=rank, world_size=2)
    try:
        pending = {"answer_parse_rate": [2.0 / 3.0]} if rank == 0 else {}
        result = flush(pending)
        assert result == {"answer_parse_rate": 2.0 / 3.0}, (rank, result)

        pending = {"shared": [0.0, 1.0], "rank0_only": [0.25]} if rank == 0 else {"shared": [1.0]}
        result = flush(pending)
        assert result == {"rank0_only": 0.25, "shared": 0.75}, (rank, result)

        assert flush({}) == {}
        dist.barrier()
        if rank == 0:
            print("PASS: rank-disjoint, shared, and empty metric flushes agree on both ranks")
    finally:
        dist.destroy_process_group()


if __name__ == "__main__":
    with tempfile.TemporaryDirectory() as directory:
        mp.spawn(worker, args=(os.path.join(directory, "store"),), nprocs=2, join=True)

